import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.springframework.stereotype.Component;

// ✅ NEW: One aspect times EVERY method matching the pointcut — no
// boilerplate in the business methods, uniform metrics, and a single
// place to change the behavior.
@Aspect
@Component
public class TimingAspect {
  private static final Logger log = LoggerFactory.getLogger(TimingAspect.class);

  // ✅ NEW: pointcut — any public method on any class in the service
  // package; @Around gives full control (pjp.proceed() runs the target).
  @Around("execution(* com.example.service..*(..))") // ✅ NEW
  public Object time(ProceedingJoinPoint pjp) throws Throwable {
    long start = System.nanoTime();
    try {
      return pjp.proceed(); // ✅ NEW: invoke the target method
    } finally {
      log.info("{} took {}ms",
          pjp.getSignature().toShortString(),
          (System.nanoTime() - start) / 1_000_000);
    }
  }
}

// Other advice types:
// @Before("...") — run before; @AfterReturning — after success;
// @AfterThrowing — after exception; @After — finally-style.
